CREATE TABLE `memberships` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`user_id` CHAR(36) CHARACTER SET ascii NOT NULL,`status` ENUM('active','disabled') NOT NULL,`joined_at` DATETIME(3) NOT NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_memberships_org_user`(`organization_id`,`user_id`),KEY `idx_memberships_user_status`(`user_id`,`status`,`organization_id`),CONSTRAINT `fk_memberships_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_memberships_user` FOREIGN KEY(`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
